}\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport class AgentIntegration {\\\\\\\\n    private conversationsByCardInternalId: Map<string, AgentConversation[]> = new Map()\\\\\\\\n    private readonly dependencies: AgentIntegrationDeps\\\\\\\\n    private errorsByCardPath: Map<string, AgentConversationError[]> = new Map()\\\\\\\\n    private reportedLoadErrorKeys: Set<string> = new Set()\\\\\\\\n    private readonly saveFile: (file: MarkdownFile) => MarkdownFile\\\\\\\\n    private scheduledRunCleanup: (() => void) | null = null\\\\\\\\n\\\\\\\\n    constructor(\\\\\\\\n        dependencies: AgentIntegrationDeps,\\\\\\\\n        saveFile: (file: MarkdownFile) => MarkdownFile,\\\\\\\\n    ) {\\\\\\\\n        this.dependencies = dependencies\\\\\\\\n        this.saveFile = saveFile\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    reset() {\\\\\\\\n        this.stopScheduledRunWatch()\\\\\\\\n        this.resetLoadedConversations()\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    resetLoadedConversations() {\\\\\\\\n        this.dependencies.beginAgentConversationLoad()\\\\\\\\n        this.conversationsByCardInternalId = new Map()\\\\\\\\n        this.errorsByCardPath = new Map()\\\\\\\\n        this.reportedLoadErrorKeys.clear()\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    startScheduledRunWatch() {\\\\\\\\n        this.stopScheduledRunWatch()\\\\\\\\n        this.scheduledRunCleanup = actionRunRegistry.subscribeActiveRunEvents((event) => {\\\\\\\\n            try {\\\\\\\\n                this.handleActionRunEvent(event)\\\\\\\\n            } catch (error) {\\\\\\\\n                telemetryService.captureError(error)\\\\\\\\n            }\\\\\\\\n        })\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    stopScheduledRunWatch() {\\\\\\\\n        if (!this.scheduledRunCleanup) return\\\\\\\\n\\\\\\\\n        this.scheduledRunCleanup()\\\\\\\\n        this.scheduledRunCleanup = null\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    async continueAgentConversation(cardPath: string, sourcePath: string) {\\\\\\\\n        const { config } = this.dependencies.requireDependencies()\\\\\\\\n        const snapshot = this.dependencies.snapshot()\\\\\\\\n        const card = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]\\\\\\\\n            .find((candidate) => candidate.path === cardPath)\\\\\\\\n        if (!card) throw new Error(`Cannot continue agent for unknown card: ${cardPath}`)\\\\\\\\n        if (!card.header.internalId) throw new Error(`Cannot continue agent for card without an internal ID: ${cardPath}`)\\\\\\\\n        const conversation = (this.conversationsByCardInternalId.get(card.header.internalId) ?? [])\\\\\\\\n            .find(({ path }) => path === sourcePath)\\\\\\\\n        if (!conversation) throw new Error(`Unknown agent conversation: ${sourcePath}`)\\\\\\\\n        const action = conversation.actionId\\\\\\\\n            ? actionService.getActions().find(({ id }) => id === conversation.actionId)\\\\\\\\n            : BUILTIN_CUSTOM_PROMPT\\\\\\\\n        if (!action) throw new Error(`Unknown originating action: ${conversation.actionId}`)\\\\\\\\n\\\\\\\\n        return runElectronAction(action, fileContext(card, config.cardTypes), { continueFrom: sourcePath })\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private saveAgentConversationReference(cardPath: string, reference: string) {\\\\\\\\n        const { config } = this.dependencies.requireDependencies()\\\\\\\\n        const existingFile = this.dependencies.requireFile(cardPath)\\\\\\\\n        const card = markdownParsingService.parseCard(existingFile, config.workingFolder)\\\\\\\\n        const nextReferences = [...new Set([...card.header.agentLogReferences, reference])]\\\\\\\\n        this.saveFile({\\\\\\\\n            content: markdownParsingService.setAgentLogReferences(existingFile.content, nextReferences),\\\\\\\\n            path: cardPath,\\\\\\\\n            sha: existingFile.sha,\\\\\\\\n        })\\\\\\\\n\\\\\\\\n        return card.header.internalId\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private linkAgentConversationReference(cardPath: string, reference: string) {\\\\\\\\n        const cardInternalId = this.saveAgentConversationReference(cardPath, reference)\\\\\\\\n        if (!cardInternalId) throw new Error(`Cannot link a card conversation without an internal ID: ${cardPath}`)\\\\\\\\n        void this.loadLinkedAgentConversation(cardInternalId, cardPath, reference)\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private async loadLinkedAgentConversation(cardInternalId: string, cardPath: string, reference: string) {\\\\\\\\n        const project = this.dependencies.project()\\\\\\\\n        if (!project) return\\\\\\\\n        const { storage } = this.dependencies.requireDependencies()\\\\\\\\n        const result = await loadAgentConversationReference({ cardInternalId, cardPath, reference }, project, storage)\\\\\\\\n        if (result.error) {\\\\\\\\n            const errors = [...(this.errorsByCardPath.get(cardPath) ?? []), result.error]\\\\\\\\n            this.errorsByCardPath.set(cardPath, errors)\\\\\\\\n            this.reportNewAgentLoadErrors(new Map([[cardPath, [result.error]]]))\\\\\\\\n            return\\\\\\\\n        }\\\\\\\\n\\\\\\\\n        this.upsertAgentConversation(cardInternalId, result.conversation)\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    async loadAgentConversationsInBackground(snapshot: ProjectSnapshot, project: ProjectReference, projectLoadToken: number) {\\\\\\\\n        const agentConversationLoadToken = this.dependencies.beginAgentConversationLoad()\\\\\\\\n\\\\\\\\n        try {\\\\\\\\n            const { config } = this.dependencies.requireDependencies()\\\\\\\\n            const cards = cardsForAgentConversationLoading(snapshot, config)\\\\\\\\n            await this.resolveAndAttachAgentConversations(cards, project, projectLoadToken, agentConversationLoadToken)\\\\\\\\n        } catch (error) {\\\\\\\\n            dialogService.warning('Agent conversations could not be loaded and were skipped.', { title: 'Some agent conversations were not loaded' })\\\\\\\\n            telemetryService.captureError(error)\\\\\\\\n        }\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    attachAgentConversations(cards: Pick<ProjectSnapshot, 'activeCards' | 'backgroundCards'>) {\\\\\\\\n        return {\\\\\\\\n            activeCards: cards.activeCards.map((card) => ({\\\\\\\\n                ...card,\\\\\\\\n                agentConversationErrors: this.errorsByCardPath.get(card.path) ?? [],\\\\\\\\n                agentConversations: card.header.internalId\\\\\\\\n                    ? this.conversationsByCardInternalId.get(card.header.internalId) ?? []\\\\\\\\n                    : [],\\\\\\\\n            })),\\\\\\\\n            backgroundCards: cards.backgroundCards.map((card) => ({\\\\\\\\n                ...card,\\\\\\\\n                agentConversationErrors: this.errorsByCardPath.get(card.path) ?? [],\\\\\\\\n                agentConversations: card.header.internalId\\\\\\\\n                    ? this.conversationsByCardInternalId.get(card.header.internalId) ?? []\\\\\\\\n                    : [],\\\\\\\\n            })),\\\\\\\\n        }\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    getAgentConversations(cardInternalId: string) {\\\\\\\\n        return this.conversationsByCardInternalId.get(cardInternalId) ?? []\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    /** Applies a persisted conversation returned by an atomic backend update. */\\\\\\\\n    updateAgentConversation(conversation: AgentConversation) {\\\\\\\\n        if (!conversation.cardInternalId) return\\\\\\\\n\\\\\\\\n        this.upsertAgentConversation(conversation.cardInternalId, conversation)\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    triggerStateActions(cardPath: string, state: string) {\\\\\\\\n        const { config } = this.dependencies.requireDependencies()\\\\\\\\n        const card = this.dependencies.snapshot()?.activeCards.find((currentCard) => currentCard.path === cardPath)\\\\\\\\n        if (!card) return\\\\\\\\n\\\\\\\\n        const context = cardContext(card, config.cardTypes)\\\\\\\\n        const actions = actionService.getActionsForStateTrigger(state, context)\\\\\\\\n        for (const action of actions) {\\\\\\\\n            void this.runStateAction(action, context, cardPath)\\\\\\\\n        }\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private async resolveAndAttachAgentConversations(\\\\\\\\n        cards: ProjectSnapshot['activeCards'],\\\\\\\\n        project: ProjectReference,\\\\\\\\n        projectLoadToken: number,\\\\\\\\n        agentConversationLoadToken: number,\\\\\\\\n    ) {\\\\\\\\n        const { config, storage } = this.dependencies.requireDependencies()\\\\\\\\n        const resolved = await resolveAgentConversations(cards, project, storage)\\\\\\\\n        if (!this.shouldApplyProjectLoad(project, projectLoadToken)) return\\\\\\\\n        if (!this.dependencies.isCurrentAgentConversationLoad(agentConversationLoadToken)) return\\\\\\\\n\\\\\\\\n        for (const [cardInternalId, conversations] of resolved.conversationsByCardInternalId) {\\\\\\\\n            const existing = this.conversationsByCardInternalId.get(cardInternalId) ?? []\\\\\\\\n            this.conversationsByCardInternalId.set(cardInternalId, mergeAgentConversations(existing, conversations))\\\\\\\\n        }\\\\\\\\n        this.errorsByCardPath = this.mergeResolvedAgentErrors(resolved.errorsByCardPath)\\\\\\\\n        this.reportNewAgentLoadErrors(resolved.errorsByCardPath)\\\\\\\\n        this.dependencies.refreshSnapshot(config.workingFolder)\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private shouldApplyProjectLoad(project: ProjectReference, projectLoadToken: number) {\\\\\\\\n        return this.dependencies.isCurrentLoad(project, projectLoadToken)\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private mergeResolvedAgentErrors(resolvedErrors: Map<string, AgentConversationError[]>) {\\\\\\\\n        const errors = new Map(resolvedErrors)\\\\\\\\n\\\\\\\\n        for (const [cardPath, existingErrors] of this.errorsByCardPath) {\\\\\\\\n            const onStateErrors = existingErrors.filter(isOnStateActionError)\\\\\\\\n            if (onStateErrors.length === 0) continue\\\\\\\\n\\\\\\\\n            errors.set(cardPath, [...(errors.get(cardPath) ?? []), ...onStateErrors])\\\\\\\\n        }\\\\\\\\n\\\\\\\\n        return errors\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private reportNewAgentLoadErrors(errorsByCardPath: Map<string, AgentConversationError[]>) {\\\\\\\\n        const newErrors: AgentConversationError[] = []\\\\\\\\n        for (const [cardPath, errors] of errorsByCardPath) {\\\\\\\\n            for (const error of errors) {\\\\\\\\n                const key = `${cardPath}:${error.path}:${error.message}`\\\\\\\\n                if (this.reportedLoadErrorKeys.has(key)) continue\\\\\\\\n\\\\\\\\n                this.reportedLoadErrorKeys.add(key)\\\\\\\\n                newErrors.push(error)\\\\\\\\n            }\\\\\\\\n        }\\\\\\\\n        if (newErrors.length === 0) return\\\\\\\\n\\\\\\\\n        const paths = newErrors.map(({ path }) => path).join(', ')\\\\\\\\n        dialogService.warning(`Some agent conversations could not be loaded and were skipped: ${paths}`, {title: 'Some agent conversations were not loaded'})\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private async runStateAction(action: ActionDefinition, context: ActionContext, cardPath: string) {\\\\\\\\n        try {\\\\\\\\n            const result = await runElectronAction(action, context, {}, undefined, false)\\\\\\\\n            if (result.status === 'completed') return\\\\\\\\n\\\\\\\\n            const failedLog = result.logs.find((log) => log.status === 'failed')\\\\\\\\n            this.recordCardAgentError(cardPath, action.id, failedLog?.message ?? `${action.label} failed`)\\\\\\\\n        } catch (error) {\\\\\\\\n            this.recordCardAgentError(cardPath, action.id, error instanceof Error ? error.message : `${action.label} failed`)\\\\\\\\n        }\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private recordCardAgentError(cardPath: string, actionName: string, message: string) {\\\\\\\\n        const path = `${ON_STATE_ACTION_ERROR_PATH_PREFIX}:${actionName}`\\\\\\\\n        const { config } = this.dependencies.requireDependencies()\\\\\\\\n        this.errorsByCardPath.set(cardPath, [...(this.errorsByCardPath.get(cardPath) ?? []), { message, path }])\\\\\\\\n        this.dependencies.refreshSnapshot(config.workingFolder)\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private handleActionRunEvent(event: ActionRunEvent) {\\\\\\\\n        if (\\\\\\\\n            event.type === 'update'\\\\\\\\n            && event.update.kind === 'agentStarted'\\\\\\\\n            && event.context.kind === 'card'\\\\\\\\n            && event.context.file\\\\\\\\n        ) {\\\\\\\\n            this.saveAgentConversationReference(event.context.file, event.update.conversation.path)\\\\\\\\n        }\\\\\\\\n        if (event.type === 'action') this.linkActionConversation(event)\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private linkActionConversation(event: ActionRunEvent) {\\\\\\\\n        if (event.type !== 'action' || event.status === 'running' || !event.context.file || !event.reference) return\\\\\\\\n\\\\\\\\n        this.linkAgentConversationReference(event.context.file, event.reference)\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    private upsertAgentConversation(cardInternalId: string, conversation: AgentConversation) {\\\\\\\\n        const { config } = this.dependencies.requireDependencies()\\\\\\\\n        const conversations = this.conversationsByCardInternalId.get(cardInternalId) ?? []\\\\\\\\n        const nextConversations = conversations.some((current) => current.id === conversation.id)\\\\\\\\n            ? conversations.map((current) => (current.id === conversation.id ? conversation : current))\\\\\\\\n            : [...conversations, conversation]\\\\\\\\n        this.conversationsByCardInternalId.set(cardInternalId, nextConversations)\\\\\\\\n        this.dependencies.refreshSnapshot(config.workingFolder)\\\\\\\\n    }\\\\\\\\n\\\\\\\\n}\\\\\\\\n\\\\\\\\r\\\\\\\\nimport { actionContextIdentity } from '../../data/action_context'\\\\\\\\nimport type { ActionContext } from '../../data/action_context'\\\\\\\\nimport type { ActionDefinition } from '../../data/action_types'\\\\\\\\nimport type { AgentConversation, AgentConversationEntry, AgentConversationEventEntry } from '../../data/data_types'\\\\\\\\nimport type {\\\\\\\\n    AgentApproval,\\\\\\\\n    AgentApprovalDecision,\\\\\\\\n    AgentApprovalRequestId,\\\\\\\\n    AgentQuestion,\\\\\\\\n    ActionRunEvent,\\\\\\\\n    ActionRunStatus,\\\\\\\\n    ActionRunTerminalStatus,\\\\\\\\n    ActionRunUpdate,\\\\\\\\n    ActionRunInput,\\\\\\\\n    ActionRunLogEntry,\\\\\\\\n    ActionRunResult,\\\\\\\\n} from '../../data/action_run_types'\\\\\\\\nimport { getElectronActionBridge } from '../../data/electron_action_bridge'\\\\\\\\nimport type { ElectronActionBridge } from '../../data/electron_action_bridge'\\\\\\\\nimport { actionService } from './action_service'\\\\\\\\nimport { actionPromptDraftService } from './action_prompt_draft_service'\\\\\\\\nimport { register } from '.././service_injector'\\\\\\\\n\\\\\\\\nconst TERMINAL_STATUSES = new Set<ActionRunTerminalStatus>(['cancelled', 'completed', 'failed', 'okButNotAfter'])\\\\\\\\nconst ACTIVE_STATUSES = new Set<ActionRunStatus>(['queued', 'running', 'waitingForInput'])\\\\\\\\nconst EMPTY_ACTIVE_RUNS: ActiveActionRun[] = []\\\\\\\\n\\\\\\\\nexport interface ActionRun {\\\\\\\\n    activeActionAutoFinish: ActionDefinition['autoFinish']\\\\\\\\n    activeActionId: string | null\\\\\\\\n    activeActionStreaming: boolean\\\\\\\\n    activeActionType: ActionDefinition['type'] | null\\\\\\\\n    conversation: AgentConversation | null\\\\\\\\n    context: ActionContext\\\\\\\\n    runId: string\\\\\\\\n    logs: ActionRunLogEntry[]\\\\\\\\n    approvals: LiveAgentApproval[]\\\\\\\\n    interactionReady: boolean\\\\\\\\n    question: LiveAgentQuestion | null\\\\\\\\n    reference: string | null\\\\\\\\n    rootActionId: string\\\\\\\\n    status: ActionRunStatus\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport interface LiveAgentApproval extends AgentApproval {\\\\\\\\n    submitted: boolean\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport interface LiveAgentQuestion {\\\\\\\\n    questions: AgentQuestion[]\\\\\\\\n    requestId: number | string | null\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport interface ActiveActionRun {\\\\\\\\n    rootActionId: string\\\\\\\\n    runId: string\\\\\\\\n    status: ActionRunStatus\\\\\\\\n}\\\\\\\\n\\\\\\\\ntype EventListener = (event: ActionRunEvent) => void\\\\\\\\ntype StoreListener = () => void\\\\\\\\n\\\\\\\\nfunction actionName(actionId: string) {\\\\\\\\n    return actionService.getActions().find((action) => action.id === actionId)?.label ?? actionId\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction actionType(actionId: string) {\\\\\\\\n    return actionService.getActions().find((action) => action.id === actionId)?.type ?? null\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction actionStreaming(actionId: string) {\\\\\\\\n    return actionService.getActions().find((action) => action.id === actionId)?.streaming ?? false\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction createLog(event: ActionRunEvent): ActionRunLogEntry {\\\\\\\\n    return {\\\\\\\\n        ...(event.type === 'action' && event.accessLevel ? { accessLevel: event.accessLevel } : {}),\\\\\\\\n        actionId: event.actionId,\\\\\\\\n        actionName: actionName(event.actionId),\\\\\\\\n        ...(event.type === 'action' && event.approvalPolicy ? { approvalPolicy: event.approvalPolicy } : {}),\\\\\\\\n        command: event.type === 'action' ? event.command ?? null : null,\\\\\\\\n        message: event.type === 'action' ? event.message ?? `${actionName(event.actionId)} ${event.status}` : `${actionName(event.actionId)} running`,\\\\\\\\n        phase: event.phase,\\\\\\\\n        status: event.status,\\\\\\\\n        stderr: '',\\\\\\\\n        stdout: '',\\\\\\\\n        ...(event.type === 'action' && event.thinkingLevel ? { thinkingLevel: event.thinkingLevel } : {}),\\\\\\\\n    }\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction runningLogIndex(logs: ActionRunLogEntry[], event: ActionRunEvent) {\\\\\\\\n    return logs.findLastIndex((log) => (\\\\\\\\n        log.actionId === event.actionId\\\\\\\\n        && log.phase === event.phase\\\\\\\\n        && (log.status === 'queued' || log.status === 'running')\\\\\\\\n    ))\\\\\\\\n}\\\\\\\\n\\\\\\\\ntype AgentOutputUpdate = Pick<\\\\\\\\n    Extract<ActionRunUpdate, { kind: 'error' | 'output' }>,\\\\\\\\n    'content' | 'previousContent' | 'replace'\\\\\\\\n>\\\\\\\\n\\\\\\\\nfunction updatedStdout(currentStdout: string, update: AgentOutputUpdate) {\\\\\\\\n    if (!update.replace) return `${currentStdout}${update.content}`\\\\\\\\n    if (update.previousContent === undefined) throw new Error('Missing previous assistant output')\\\\\\\\n    if (!currentStdout.endsWith(update.previousContent)) throw new Error('Assistant output replacement is out of order')\\\\\\\\n\\\\\\\\n    return `${currentStdout.slice(0, currentStdout.length - update.previousContent.length)}${update.content}`\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction updateActionLogs(logs: ActionRunLogEntry[], event: Extract<ActionRunEvent, { type: 'action' }>) {\\\\\\\\n    const currentIndex = runningLogIndex(logs, event)\\\\\\\\n    if (currentIndex < 0) return [...logs, createLog(event)]\\\\\\\\n    const current = logs[currentIndex]\\\\\\\\n    const next = [...logs]\\\\\\\\n    next[currentIndex] = {\\\\\\\\n        ...current,\\\\\\\\n        ...(event.accessLevel ? { accessLevel: event.accessLevel } : {}),\\\\\\\\n        ...(event.approvalPolicy ? { approvalPolicy: event.approvalPolicy } : {}),\\\\\\\\n        command: event.command ?? current.command,\\\\\\\\n        message: event.message ?? `${actionName(event.actionId)} ${event.status}`,\\\\\\\\n        status: event.status,\\\\\\\\n        ...(event.thinkingLevel ? { thinkingLevel: event.thinkingLevel } : {}),\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    return next\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction updateOutputLogs(\\\\\\\\n    logs: ActionRunLogEntry[],\\\\\\\\n    event: Extract<ActionRunEvent, { type: 'update' }>,\\\\\\\\n    update: Extract<ActionRunUpdate, { kind: 'error' | 'output' }>,\\\\\\\\n) {\\\\\\\\n    const currentIndex = logs.findLastIndex((log) => (\\\\\\\\n        log.actionId === event.actionId && log.phase === event.phase && log.status === 'running'\\\\\\\\n    ))\\\\\\\\n    const current = currentIndex >= 0 ? logs[currentIndex] : createLog(event)\\\\\\\\n    const updated = {\\\\\\\\n        ...current,\\\\\\\\n        command: update.command ?? current.command,\\\\\\\\n        stderr: update.kind === 'error' ? `${current.stderr}${update.content}` : current.stderr,\\\\\\\\n        stdout: update.kind === 'output' ? updatedStdout(current.stdout, update) : current.stdout,\\\\\\\\n    }\\\\\\\\n    if (currentIndex < 0) return [...logs, updated]\\\\\\\\n    const next = [...logs]\\\\\\\\n    next[currentIndex] = updated\\\\\\\\n\\\\\\\\n    return next\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction eventIdentity(event: AgentConversationEventEntry) {\\\\\\\\n    return event.providerItemId ?? event.id\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction upsertAgentEvent(entries: AgentConversationEntry[], event: AgentConversationEventEntry) {\\\\\\\\n    const identity = eventIdentity(event)\\\\\\\\n    const currentIndex = entries.findIndex((entry) => entry.kind === 'event' && eventIdentity(entry) === identity)\\\\\\\\n    if (currentIndex < 0) return [...entries, event]\\\\\\\\n\\\\\\\\n    const current = entries[currentIndex]\\\\\\\\n    const next = [...entries]\\\\\\\\n    next[currentIndex] = {\\\\\\\\n        ...event,\\\\\\\\n        ...(event.sequence === undefined && current.sequence !== undefined ? { sequence: current.sequence } : {}),\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    return next\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction nextConversationSequence(conversation: AgentConversation) {\\\\\\\\n    const sequences = conversation.entries.map(({ sequence }) => sequence)\\\\\\\\n        .filter((sequence): sequence is number => sequence !== undefined)\\\\\\\\n\\\\\\\\n    return sequences.length > 0 ? Math.max(...sequences) + 1 : undefined\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction appendAssistantMessage(\\\\\\\\n    conversation: AgentConversation,\\\\\\\\n    update: { content: string, messageId?: string, replace?: boolean, sequence?: number },\\\\\\\\n) {\\\\\\\\n    const sequence = update.sequence ?? nextConversationSequence(conversation)\\\\\\\\n    const latestUserIndex = conversation.entries.findLastIndex((entry) => entry.kind === 'message' && entry.role === 'user')\\\\\\\\n    const currentAssistantMessage = conversation.entries.slice(latestUserIndex + 1)\\\\\\\\n        .findLast((entry) => entry.kind === 'message' && entry.role === 'assistant')\\\\\\\\n    const messageId = update.messageId\\\\\\\\n        ?? currentAssistantMessage?.id\\\\\\\\n        ?? `${conversation.id}-assistant-${sequence ?? conversation.entries.length + 1}`\\\\\\\\n    const currentIndex = conversation.entries.findIndex((entry) => entry.kind === 'message' && entry.id === messageId)\\\\\\\\n    const entries: AgentConversationEntry[] = currentIndex < 0\\\\\\\\n        ? [...conversation.entries, {\\\\\\\\n            content: update.content,\\\\\\\\n            id: messageId,\\\\\\\\n            kind: 'message',\\\\\\\\n            role: 'assistant' as const,\\\\\\\\n            ...(sequence !== undefined ? { sequence } : {}),\\\\\\\\n            timestamp: conversation.startedAt,\\\\\\\\n        }]\\\\\\\\n        : conversation.entries.map((entry, index) => index === currentIndex\\\\\\\\n            ? { ...entry, content: update.replace ? update.content : `${entry.content}${update.content}` }\\\\\\\\n            : entry)\\\\\\\\n\\\\\\\\n    return { ...conversation, entries }\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction conversationStatus(status: ActionRunStatus): AgentConversation['status'] {\\\\\\\\n    if (status === 'queued') return 'running'\\\\\\\\n    if (status === 'okButNotAfter') return 'completed'\\\\\\\\n\\\\\\\\n    return status\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction contextKey(context: ActionContext) {\\\\\\\\n    return actionContextIdentity(context)\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport async function cancelActionRun(runId: string) {\\\\\\\\n    const bridge = getElectronActionBridge()\\\\\\\\n    if (!bridge) throw new Error('Action cancellation requires Electron')\\\\\\\\n\\\\\\\\n    await bridge.cancelActionRun(runId)\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport async function sendActionMessage(runId: string, content: string) {\\\\\\\\n    const bridge = getElectronActionBridge()\\\\\\\\n    if (!bridge?.sendActionMessage) throw new Error('Streaming agent messaging requires Electron')\\\\\\\\n\\\\\\\\n    await bridge.sendActionMessage(runId, content)\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport async function answerActionQuestion(\\\\\\\\n    runId: string,\\\\\\\\n    requestId: number | string | null,\\\\\\\\n    answers: Record<string, string[]>,\\\\\\\\n) {\\\\\\\\n    const bridge = getElectronActionBridge()\\\\\\\\n    if (!bridge?.answerActionQuestion) throw new Error('Streaming agent questions require Electron')\\\\\\\\n\\\\\\\\n    await bridge.answerActionQuestion(runId, requestId, answers)\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport async function answerActionApproval(\\\\\\\\n    runId: string,\\\\\\\\n    requestId: AgentApprovalRequestId,\\\\\\\\n    decision: AgentApprovalDecision,\\\\\\\\n) {\\\\\\\\n    const bridge = getElectronActionBridge()\\\\\\\\n    if (!bridge?.answerActionApproval) throw new Error('Streaming agent approvals require Electron')\\\\\\\\n\\\\\\\\n    await bridge.answerActionApproval(runId, requestId, decision)\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport async function finishActionRun(runId: string) {\\\\\\\\n    const bridge = getElectronActionBridge()\\\\\\\\n    if (!bridge?.finishActionRun) throw new Error('Finishing a streaming agent requires Electron')\\\\\\\\n\\\\\\\\n    await bridge.finishActionRun(runId)\\\\\\\\n}\\\\\\\\n\\\\\\\\nexport async function notifyActionCardStateChange(cardInternalId: string | null, state: string) {\\\\\\\\n    if (!cardInternalId) return\\\\\\\\n    const bridge = getElectronActionBridge()\\\\\\\\n    if (!bridge?.notifyActionCardStateChange) throw new Error('Automatic agent finish requires Electron')\\\\\\\\n\\\\\\\\n    await bridge.notifyActionCardStateChange(cardInternalId, state)\\\\\\\\n}\\\\\\\\n\\\\\\\\n/** Stable state owner for one action run. */\\\\\\\\nexport class ActionRunStore {\\\\\\\\n    private readonly listeners = new Set<StoreListener>()\\\\\\\\n    private readonly onReleased: (store: ActionRunStore) => void\\\\\\\\n    private snapshot: ActionRun\\\\\\\\n\\\\\\\\n    constructor(snapshot: ActionRun, onReleased: (store: ActionRunStore) => void) {\\\\\\\\n        this.onReleased = onReleased\\\\\\\\n        this.snapshot = snapshot\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    readonly getSnapshot = () => this.snapshot\\\\\\\\n\\\\\\\\n    readonly subscribe = (listener: StoreListener) => {\\\\\\\\n        this.listeners.add(listener)\\\\\\\\n\\\\\\\\n        return () => {\\\\\\\\n            this.listeners.delete(listener)\\\\\\\\n            this.onReleased(this)\\\\\\\\n        }\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    hasConsumers() {\\\\\\\\n        return this.listeners.size > 0\\\\\\\\n    }\\\\\\\\n\\\\\\\\n    update(snapshot: ActionRun) {\\\\\\\\n        this.snapshot = snapshot\\\\\\\\n        for (const listener of this.listeners) listener()\\\\\\\\n    }\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction actionContextKey(actionId: string, context: ActionContext) {\\\\\\\\n    return `${actionId}\\\\\\\\\\\\\\\\u0000${contextKey(context)}`\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction activeRun(run: ActionRun): ActiveActionRun {\\\\\\\\n    return { rootActionId: run.rootActionId, runId: run.runId, status: run.status }\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction sameActiveRuns(first: ActiveActionRun[], second: ActiveActionRun[]) {\\\\\\\\n    return first.length === second.length && first.every(({ runId, status }, index) => (\\\\\\\\n        second[index]?.runId === runId && second[index]?.status === status\\\\\\\\n    ))\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction publishKey(map: Map<string, Set<StoreListener>>, key: string) {\\\\\\\\n    const listeners = map.get(key) ?? []\\\\\\\\n    for (const listener of listeners) listener()\\\\\\\\n}\\\\\\\\n\\\\\\\\nfunction publishListeners(map: Map<string, Set<StoreListener>>) {\\\\\\\\n    for (const listeners of map.values()) {\\\\\\\\n        for (const listener of listeners) listener()\\\\\\\\n    }\\\\\\\\n}\\\\\\\\n\\\\\\\\n/** Owns one renderer-wide bridge subscription and routes events to scoped run stores. */\\\\\\\\nexport class ActionRunRegistry extends EventTarget {\\\\\\\\n    private readonly actionContextListeners = new Map<string, Set<StoreListener>>()\\\\\\\\n    private readonly actionContextStores = new Map<string, ActionRunStore>()\\\\\\\\n    private readonly activeRunEventListeners = new Set<EventListener>()\\\\\\\\n    private readonly contextActiveListeners = new Map<string, Set<StoreListener>>()\\\\\\\\n    private readonly contextActiveSnapshots = new Map<string, ActiveActionRun[]>()\\\\\\\\n    private readonly contextEventListeners = new Map<string, Set<EventListener>>()\\\\\\\\n    private eventSequences = new Map<string, number>()\\\\\\\\n    private readonly globalActiveListeners = new Set<StoreListener>()\\\\\\\\n    private globalActiveSnapshot: ActiveActionRun[] = EMPTY_ACTIVE_RUNS\\\\\\\\n    private recoveryEvents: ActionRunEvent[] | null = null\\\\\\\\n    private runs = new Map<string, ActionRunStore>()\\\\\\\\n    private subscribedBridge: ElectronActionBridge | null = null\\\\\\\\n    private startsInProgress = 0\\\\\\\\n    private readonly terminalResults = new Map<string, ActionRunResult>()\\\\\\\\n    private unsubscribeBridge: (() => void) | null = null\\\\\\\\n    private readonly waiters = new Map<string, Set<(